import java.util.*;
import java.io.*;

public class Main {
    static int[][][][] shortestDist = new int[15][15][15][15];
    static int[][] capacity = new int[400][400];
    static char[][] scienceMap = new char[20][20];
    static char[][] reactionMap = new char[20][20];
    static int[] deltaX = {1, 0, -1, 0};
    static int[] deltaY = {0, 1, 0, -1};
    static int currentIter = 3;
    static int[] visitedNodes = new int[400];
    static int nSize, maxTime;
    static int[][] reachability = new int[13][13];
    static int[][] tempReach = new int[13][13];

    static int augmentFlow(int current, int target, int flow) {
        if (current == target) return flow;
        if (visitedNodes[current] == currentIter) return 0;
        visitedNodes[current] = currentIter;
        for (int i = 0; i <= target; i++) {
            if (capacity[current][i] > 0) {
                int pushed = augmentFlow(i, target, Math.min(flow, capacity[current][i]));
                if (pushed > 0) {
                    capacity[current][i] -= pushed;
                    capacity[i][current] += pushed;
                    return pushed;
                }
            }
        }
        return 0;
    }

    static int nodeID(int x, int y) {
        return (x - 1) * nSize + y - 1;
    }

    static void propagate(int val) {
        for (int i = 1; i <= nSize; i++)
            for (int j = 1; j <= nSize; j++)
                tempReach[i][j] = reachability[i][j];

        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                if (tempReach[i][j] == val) {
                    for (int dir = 0; dir < 4; dir++) {
                        int ni = i + deltaX[dir], nj = j + deltaY[dir];
                        if (ni > 0 && nj > 0 && ni <= nSize && nj <= nSize && tempReach[ni][nj] < val && scienceMap[ni][nj] != 'Y') {
                            reachability[ni][nj] = val;
                        }
                    }
                }
            }
        }
    }

    static boolean isReachable(int sx, int sy, int tx, int ty, int ix, int iy) {
        for (int i = 0; i < reachability.length; i++)
            Arrays.fill(reachability[i], 0);
        reachability[sx][sy] = 1;
        reachability[ix][iy] = 2;
        for (int i = 0; i < 100; i++) {
            propagate(1);
            if (reachability[tx][ty] == 1) return true;
            propagate(2);
            if (reachability[tx][ty] == 2) return false;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int infX = 0, infY = 0;
        for (int i = 0; i < shortestDist.length; i++)
            for (int j = 0; j < shortestDist[i].length; j++)
                for (int k = 0; k < shortestDist[i][j].length; k++)
                    for (int l = 0; l < shortestDist[i][j][k].length; l++)
                        shortestDist[i][j][k][l] = 1000000000;
        nSize = Integer.parseInt(st.nextToken());
        maxTime = Integer.parseInt(st.nextToken());
        for (int i = 1; i <= nSize; i++) {
            String line = br.readLine();
            for (int j = 1; j <= nSize; j++) {
                scienceMap[i][j] = line.charAt(j - 1);
                shortestDist[i][j][i][j] = 0;
                if (scienceMap[i][j] == 'Z') {
                    infX = i;
                    infY = j;
                }
            }
        }
        for (int i = 1; i <= nSize; i++) {
            String line = br.readLine();
            for (int j = 1; j <= nSize; j++) {
                reactionMap[i][j] = line.charAt(j - 1);
            }
        }
        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                for (int dir = 0; dir < 4; dir++) {
                    int ni = i + deltaX[dir], nj = j + deltaY[dir];
                    if (ni > 0 && ni <= nSize && nj > 0 && nj <= nSize) {
                        if (scienceMap[i][j] != 'Y' && scienceMap[ni][nj] != 'Y') {
                            shortestDist[i][j][ni][nj] = 1;
                        }
                    }
                }
            }
        }
        for (int ki = 1; ki <= nSize; ki++) {
            for (int kj = 1; kj <= nSize; kj++) {
                for (int ii = 1; ii <= nSize; ii++) {
                    for (int ij = 1; ij <= nSize; ij++) {
                        for (int ji = 1; ji <= nSize; ji++) {
                            for (int jj = 1; jj <= nSize; jj++) {
                                shortestDist[ii][ij][ji][jj] = Math.min(
                                    shortestDist[ii][ij][ji][jj],
                                    shortestDist[ii][ij][ki][kj] + shortestDist[ki][kj][ji][jj]
                                );
                            }
                        }
                    }
                }
            }
        }
        int sourceNode = nSize * nSize * 2 + 1;
        int sinkNode = nSize * nSize * 2 + 2;
        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                if (Character.isDigit(scienceMap[i][j])) {
                    capacity[sourceNode][nodeID(i, j)] = scienceMap[i][j] - '0';
                }
                if (Character.isDigit(reactionMap[i][j])) {
                    capacity[nSize * nSize + nodeID(i, j)][sinkNode] = reactionMap[i][j] - '0';
                }
                if (Character.isDigit(scienceMap[i][j])) {
                    for (int ki = 1; ki <= nSize; ki++) {
                        for (int kj = 1; kj <= nSize; kj++) {
                            if (scienceMap[i][j] > '0' && reactionMap[ki][kj] > '0') {
                                if (Character.isDigit(reactionMap[ki][kj]) && shortestDist[i][j][ki][kj] <= maxTime && isReachable(i, j, ki, kj, infX, infY)) {
                                    capacity[nodeID(i, j)][nSize * nSize + nodeID(ki, kj)] = 1000;
                                }
                            }
                        }
                    }
                }
            }
        }
        int totalFlow = 0, flowVal;
        while ((flowVal = augmentFlow(sourceNode, sinkNode, 1000)) > 0) {
            totalFlow += flowVal;
            currentIter++;
        }
        System.out.println(totalFlow);
    }
}
